import {escapeHtml as h,number} from './domain.js';
import {planetArt,badge,civilizationBadge} from './art.js';
export const shipTypes={scout:{name:'Scout',cost:2000,hours:2,capacity:0,description:'Reconnaissance · combat spatial léger'},bomber:{name:'Bombardier',cost:12000,hours:8,capacity:10,description:'Appui au sol · transport de troupes'},fighter:{name:'Destroyer',cost:16000,hours:10,capacity:10,description:'Supériorité spatiale · transport de troupes'}};
const money=v=>number(v)+' Þ';
const decimal=v=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(Number(v)||0);
const date=v=>new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v));
const errorBox='<p class="form-error" role="alert" hidden></p>';
const input=(name,label,max,value=0)=>`<label>${label}<input type="number" name="${name}" min="0" max="${max}" value="${value}" step="1" required></label>`;
const shipSymbol=kind=>`<svg class="ship-symbol ${kind}" aria-hidden="true" viewBox="0 0 120 100"><path d="${kind==='scout'?'M60 5 76 50 110 78 70 70 60 94 50 70 10 78 44 50Z':kind==='bomber'?'M60 5 80 30 80 53 108 62 108 90 68 80 60 94 52 80 12 90 12 62 40 53 40 30Z':'M60 3 74 47 116 83 79 75 70 95 60 82 50 95 41 75 4 83 46 47Z'}"/><path class="ship-cockpit" d="M60 24 66 52 60 61 54 52Z"/><path class="ship-trails" d="M48 85v11M72 85v11"/></svg>`;
export function militaryDestinations(signals,originId,query=''){
 const origin=signals.find(p=>p.id===originId);if(!origin)return [];
 const term=query.trim().toLocaleLowerCase('fr');
 return signals.filter(p=>p.id!==originId&&(!term||p.designation.toLocaleLowerCase('fr').includes(term))).map(p=>({...p,distance:Math.hypot(p.x-origin.x,p.y-origin.y)})).sort((a,b)=>term?(Number(b.designation.toLocaleLowerCase('fr')===term)-Number(a.designation.toLocaleLowerCase('fr')===term)||a.distance-b.distance):a.distance-b.distance).slice(0,15);
}
export function travelSeconds(distance){return Math.max(60,Math.ceil(distance/Math.sqrt(2000000)*691200));}
export function timeLeft(at,now=Date.now()){
 const seconds=Math.max(0,Math.ceil((new Date(at).getTime()-now)/1000));if(!seconds)return 'Arrivée à confirmer';const hours=Math.floor(seconds/3600),minutes=Math.floor(seconds%3600/60);return hours>=24?`${Math.floor(hours/24)} j ${hours%24} h`:`${hours} h ${String(minutes).padStart(2,'0')} min`;
}
const countdown=at=>`<time datetime="${h(at)}" data-countdown="${h(at)}">${timeLeft(at)}</time>`;
function fleetUnits(f){return `<div class="fleet-units"><span>${shipSymbol('scout')}<b>${number(f.scouts)}</b> scouts</span><span>${shipSymbol('bomber')}<b>${number(f.bombers)}</b> bombardiers</span><span>${shipSymbol('fighter')}<b>${number(f.fighters)}</b> destroyers</span><span><b>${number(f.soldiers)}</b> embarqués</span><span><b>${number(f.ground_soldiers)}</b> au sol</span></div>`;}
function fleetPanel(f){
 const capacity=10*(f.bombers+f.fighters),moving=f.status==='transit';
 return `<article class="fleet-row"><div class="fleet-heading"><div><span class="eyebrow">${moving?'EN TRANSIT':f.mission==='attack'?'POSITION OFFENSIVE':'POSITION DÉFENSIVE'}</span><h3>${h(f.name)}</h3><p>${moving?`${h(f.origin)} → ${h(f.destination)}`:h(f.location)}</p></div><div class="fleet-status">${moving?countdown(f.arrives_at):f.lands_at?`Débarquement après ${date(f.lands_at)}`:'Stationnée'}</div></div>${fleetUnits(f)}${moving?'':`<div class="fleet-actions"><form data-military="load" data-fleet="${h(f.id)}" class="load-troops">${input('soldiers','Soldats embarqués',capacity,f.soldiers)}<span class="transport-capacity">/ ${capacity}</span><button type="submit" class="secondary">Charger / décharger</button>${errorBox}</form>${f.scouts+f.bombers+f.fighters?`<button class="secondary" data-mission-fleet="${h(f.id)}">Donner un ordre →</button>`:''}${f.own_location?`<form data-military="disband" data-fleet="${h(f.id)}"><button class="text-button" type="submit">Rendre les unités à la planète</button>${errorBox}</form>`:''}</div>`}</article>`;
}
export function militaryView(data,selectedId,pending){
 if(!data)return '<p class="empty">Établissement des communications militaires…</p>';
 const p=data.planets.find(p=>p.id===selectedId)||data.planets[0];
 return `<div class="military-page">${pending?`<div class="military-pending"><p>Un ordre attend sa confirmation.</p><button class="secondary" id="retry-military">Reprendre cet ordre</button></div>`:''}${data.debt>0?'<p class="form-error">Entretien à régulariser : les nouveaux achats sont suspendus.</p>':''}${p?`<section class="military-world"><img src="${planetArt(p.race+'_'+p.resource)}" alt="" width="150" height="150"><div><span class="eyebrow">COMMANDEMENT PLANÉTAIRE</span><label class="field">Planète<select id="military-world">${data.planets.map(w=>`<option value="${h(w.id)}" ${w.id===p.id?'selected':''}>${h(w.name)}</option>`).join('')}</select></label><div class="military-traits">${badge('race',p.race)}${badge('resource',p.resource)}${civilizationBadge()}<b>${p.civilization}</b></div></div><div class="recruitment-status"><strong>${decimal(p.daily_recruits)}</strong><span>soldats / jour</span><small>${number(p.soldiers)} en garnison</small><form data-military="recruitment" data-planet="${h(p.id)}"><input type="hidden" name="enabled" value="${!p.recruitment_enabled}"><button class="recruitment-toggle ${p.recruitment_enabled?'enabled':''}" type="submit" aria-pressed="${p.recruitment_enabled}"><i></i>${p.recruitment_enabled?'Recrutement actif':'Recrutement arrêté'}</button>${errorBox}</form></div></section>
 <section class="shipyard"><div class="military-section-heading"><div><span class="eyebrow">INDUSTRIE ORBITALE</span><h2>Chantiers spatiaux</h2></div><span><b>${p.factories-p.busy_factories}</b> / ${p.factories} usines libres</span><form data-military="factory" data-planet="${h(p.id)}" data-expected-factories="${p.factories}"><button class="secondary" type="submit" ${data.jobs.some(j=>j.planet_id===p.id&&j.kind==='factory')||p.factories>=200?'disabled':''}>Construire une usine · ${money(p.factory_price)} · ${decimal(p.factory_hours)} h</button>${errorBox}</form></div><div class="ship-production">${Object.entries(shipTypes).map(([kind,s])=>`<article>${shipSymbol(kind)}<div><h3>${s.name}</h3><p>${s.description}</p><small>${money(s.cost)} · ${decimal(s.hours/(p.resource==='ferros'?1.15:1))} h</small></div><form data-military="ship" data-planet="${h(p.id)}"><input type="hidden" name="kind" value="${kind}"><label class="visually-hidden" for="ship-${kind}">Nombre de ${s.name.toLowerCase()}s</label><input id="ship-${kind}" name="quantity" type="number" min="1" max="${Math.max(1,p.factories-p.busy_factories)}" value="1" required><button class="secondary" type="submit" ${p.factories===p.busy_factories?'disabled':''}>Produire</button>${errorBox}</form></article>`).join('')}</div>${data.jobs.filter(j=>j.planet_id===p.id).length?`<ol class="military-jobs">${data.jobs.filter(j=>j.planet_id===p.id).map(j=>`<li><span>${j.kind==='factory'?'Nouvelle usine':shipTypes[j.kind].name}</span><div class="build-progress"><i style="width:${Math.max(0,Math.min(100,(new Date(data.server_now)-new Date(j.started_at))/(new Date(j.finishes_at)-new Date(j.started_at))*100))}%"></i></div>${countdown(j.finishes_at)}</li>`).join('')}</ol>`:''}</section>
 <section class="assemble-fleet"><div><span class="eyebrow">UNITÉS EN RÉSERVE</span><h2>Constituer une flotte</h2><p>${p.scouts} scouts · ${p.bombers} bombardiers · ${p.fighters} destroyers</p></div><form data-military="assemble" data-planet="${h(p.id)}"><label>Nom de la flotte<input name="name" maxlength="40" minlength="1" value="Flotte de ${h(p.name.slice(0,25))}" required></label>${input('scouts','Scouts',p.scouts)}${input('bombers','Bombardiers',p.bombers)}${input('fighters','Destroyers',p.fighters)}<button class="secondary" type="submit">Constituer →</button>${errorBox}</form></section>`:'<p class="empty">Aucun monde contrôlé. Vos forces restent disponibles ci-dessous.</p>'}
 <section class="fleet-roster"><div class="military-section-heading"><div><span class="eyebrow">FORCES EXPÉDITIONNAIRES</span><h2>Vos flottes</h2></div><span>${data.fleets.length} détachements</span></div>${data.fleets.length?data.fleets.map(fleetPanel).join(''):'<p class="empty">Vos premières expéditions attendent leurs vaisseaux.</p>'}</section><section id="mission-orders" class="mission-orders" hidden></section></div>`;
}
export function missionView(fleet,signals){return `<div class="military-section-heading"><h2>Ordre de mission · ${h(fleet.name)}</h2><button class="text-button" id="close-mission">Fermer</button></div><form data-military="dispatch" data-fleet="${h(fleet.id)}"><label class="field">Rechercher une planète<input id="mission-search" type="search" placeholder="Nom de la planète" autocomplete="off"></label><label class="field">Destination<select name="target_id" id="mission-destination" required></select></label><p id="mission-eta" class="form-note"></p><label class="field">Mission<select name="mission"><option value="defend">Défense / renfort</option><option value="attack">Attaque</option></select></label><button class="primary" type="submit">Envoyer la flotte →</button>${errorBox}</form>`;}
export function bindMissionDestinations(root,signals,originId){
 const search=root.querySelector('#mission-search'),select=root.querySelector('#mission-destination'),eta=root.querySelector('#mission-eta');let choices=[];
 const updateETA=()=>{const target=choices.find(p=>p.id===select.value);eta.textContent=target?`Distance ${decimal(target.distance)} · voyage ${timeLeft(new Date(Date.now()+travelSeconds(target.distance)*1000))}`:'Aucune destination correspondante.';};
 const update=()=>{choices=militaryDestinations(signals,originId,search.value);select.innerHTML=choices.map(p=>`<option value="${h(p.id)}">${h(p.designation)}${p.clan_name?` [${h(p.clan_name)}]`:''}</option>`).join('');updateETA();};search.addEventListener('input',update);select.addEventListener('change',updateETA);update();
}
export function foreignPresenceView(data){const presence=data?.presence||[];return presence.length?`<section class="foreign-presence"><div class="military-section-heading"><div><span class="eyebrow">PRÉSENCE EXTÉRIEURE</span><h2>Vos forces sur d’autres mondes</h2></div></div>${presence.map(p=>`<button class="foreign-world" data-page="fleets"><img src="${planetArt(p.appearance,true)}" alt="" width="52" height="52"><span><b>${h(p.name)}</b><small>${p.attacking?'En attaque':'En défense'}</small></span><span>${number(p.ships)} vaisseaux · ${number(p.soldiers)} au sol · ${number(p.embarked)} embarqués</span><span>Gérer →</span></button>`).join('')}</section>`:'';}
export function battleReportsView(data,unreadIds=[]){
 const reports=data?.reports||[];return `<section class="battle-reports"><div class="military-section-heading"><div><span class="eyebrow">JOURNAL DES OPÉRATIONS</span><h2>Rapports de bataille</h2></div><span>${reports.length} derniers rapports</span></div>${reports.length?reports.map(r=>`<details class="battle-report ${unreadIds.includes(r.id)?'is-unread':''}"><summary><span class="report-event ${h(r.event)}">${({capture:'Conquête',arrival:'Arrivée',battle:'Combat'})[r.event]||'Opération'}</span><b>${h(r.planet)}</b><time>${date(r.occurred_at)}</time></summary><div class="report-body">${r.event==='arrival'?`<p>${h(r.details.fleet)} a rejoint ce monde en ${r.details.mission==='attack'?'attaque':'défense'}. Débarquement au premier combat horaire après ${date(r.details.lands_at)}.</p>`:`<p>${r.details.captured?'Vous avez pris le contrôle de cette planète.':r.details.mission==='attack'?'Vos forces combattent en attaque.':'Vos forces combattent en défense.'}</p><table><thead><tr><th>Vos unités</th><th>Avant</th><th>Restantes</th><th>Pertes</th></tr></thead><tbody>${['scouts','bombers','fighters','soldiers'].map(k=>`<tr><th>${({scouts:'Scouts',bombers:'Bombardiers',fighters:'Destroyers',soldiers:'Soldats'})[k]}</th><td>${number(r.details.before[k])}</td><td>${number(r.details.after[k])}</td><td>${number(Math.max(0,r.details.before[k]-r.details.after[k]))}</td></tr>`).join('')}</tbody></table><p>Forces spatiales opposées observées : ${number(r.details.enemy_space.scouts)} scouts · ${number(r.details.enemy_space.bombers)} bombardiers · ${number(r.details.enemy_space.fighters)} destroyers.</p><p>${r.details.enemy_ground===null?'Forces au sol non observées.':`${number(r.details.enemy_ground)} soldats opposés observés au sol.`}</p>`}</div></details>`).join(''):'<p class="empty">Aucun engagement signalé. Les arrivées et combats de vos forces apparaîtront ici.</p>'}</section>`;
}
export const militaryHelp=`<h3>Armées, chantiers et expéditions</h3><p>Le recrutement progresse chaque heure, avec fractions conservées. Base alpha : 1,5 soldat par jour × population en millions × civilisation. Conseil multiplie par 0,8, Tyrannie par 1,2, Biomasse par 1,15. La garnison recrute jusqu’à un soldat pour 1 000 habitants ; désactiver le recrutement conserve la fraction acquise. Les mondes neutres ne recrutent pas.</p><p>Chaque monde commence avec cinq usines. Une usine produit un vaisseau à la fois. Scouts : 2 000 Þ / 2 h ; bombardiers : 12 000 Þ / 8 h ; destroyers : 16 000 Þ / 10 h. Ferros divise ces durées par 1,15. La sixième usine coûte 25 000 Þ et prend 24 h ; prix du rang n : 25 000 × (n/6)^1,6, durée : 24 × [1 + 0,08 × (n − 6)] h, avant Ferros. Un seul chantier d’usine par planète, jusqu’à 200 usines.</p><p>Constituez une flotte avec vos vaisseaux disponibles puis chargez les soldats. Scouts sans transport ; chaque bombardier ou destroyer embarque dix soldats. Le trajet conserve l’entretien, et ses unités sont immédiatement retirées de leur origine. Une traversée diagonale complète prend huit jours ; les voyages très courts durent au moins une minute. Les soldats débarquent au premier combat horaire situé au moins une heure après l’arrivée. Une flotte peut repartir en laissant ses troupes au sol, ou les réembarquer avec des transports présents.</p><p>Les missions défensives combattent ensemble contre les missions offensives, elles aussi regroupées. Proposition alpha active : scout puissance spatiale 1 / résistance 2 ; destroyer 8 / 12 ; bombardier 0 / 10 et frappe au sol de 2 par heure. Soldat puissance et résistance 1. Chaque heure, les dégâts spatiaux et terrestres sont simultanés : 12 % de la puissance opposée, répartis proportionnellement, avec fractions conservées. Les bombardiers ne tirent pas sur les vaisseaux ; les destroyers ne bombardent pas. Les bonus de race suivent l’origine des unités. La perte des transports entraîne celle de leurs passagers à proportion.</p><p>Après élimination des défenseurs au sol et en orbite, les attaquants ayant des soldats débarqués prennent la planète. Le groupe ayant le plus de soldats désigne le conquérant ; égalité départagée de façon stable. Plafond : douze mondes. Les usines, la race et la ressource sont conservées ; les constructions inachevées sont interrompues, sans remboursement. Les forces offensives survivantes passent en défense. Un renommage est disponible après capture. Les rapports montrent vos pertes, les forces spatiales observées et les forces terrestres seulement lorsque vous avez des soldats débarqués. Ces valeurs sont un équilibrage provisoire pour l’alpha.</p>`;
